Object.assign(COW_MESSAGES.en,{"cowCareJob": "Co-op Care Job", "cowRecoveryHelp": "Use owned supplies, free cleaning/disposal, milk delivery and affordable Market resupply first. An eligible shortage opens an 8-game-hour care job. Completion rechecks the shortage and grants only missing Cow-only feed/water for up to 24 hot hours. No Coins, milk or shared water; at least 24 hours between completions. Use the shared game clock or Next day; all farm areas advance normally.", "cowAllUsableSupplies": "All usable owned Cow supplies (including shared water)", "cowStartCareJob": "Start care job", "cowCompleteCareJob": "Complete care job", "cowCareJobEligible": "Genuine shortage: this care job is available.", "cowNoCareJob": "Start an eligible care job first.", "cowCareJobActive": "One care job is already active.", "cowRecoveryRationPending": "Place the remaining care-job entitlement before requesting another. It stays available when a trough is full.", "cowCareJobCooldown": "At least 24 absolute game hours must pass between completed jobs.", "cowUseSuppliesFirst": "Owned supplies can meet the next hour. Place or use them first.", "cowUseMilkFirst": "Deliver saleable milk first. Free cleaning/disposal can unblock a ready reservoir before requesting aid.", "cowUseMarketFirst": "You can afford the missing minimum resupply. Use the normal Market route.", "cowCareJobWait": "Work for 8 ordinary game hours before completion. Eligibility is checked again.", "cowCareJobStarted": "Care job started. Advance ordinary shared game time; there is no wall-clock wait.", "cowCareJobCompleted": "Restricted care-job ration earned once. Place it into Cow troughs; unplaced entitlement is retained.", "cow_recovery_grant": "Restricted Co-op care-job ration"});

Object.assign(COW_MESSAGES.id,{"cowCareJob": "Tugas Perawatan Koperasi", "cowRecoveryHelp": "Gunakan stok, bersihkan/buang gratis, kirim susu, dan beli persediaan Pasar yang terjangkau dahulu. Kekurangan yang memenuhi syarat membuka tugas 8 jam game. Saat selesai, syarat diperiksa lagi dan hanya kekurangan pakan/air khusus Sapi hingga 24 jam panas yang diberikan. Tanpa Koin, susu, atau air tandon bersama; jarak penyelesaian minimal 24 jam. Pakai waktu game bersama atau Hari berikutnya; semua area tetap berjalan biasa.", "cowAllUsableSupplies": "Semua stok Sapi yang bisa dipakai (termasuk air bersama)", "cowStartCareJob": "Mulai tugas perawatan", "cowCompleteCareJob": "Selesaikan tugas perawatan", "cowCareJobEligible": "Persediaan benar-benar kurang: tugas ini tersedia.", "cowNoCareJob": "Mulai tugas yang memenuhi syarat dahulu.", "cowCareJobActive": "Satu tugas perawatan sedang aktif.", "cowRecoveryRationPending": "Tempatkan sisa hak jatah tugas dahulu sebelum meminta lagi. Jatah tetap tersedia saat palung penuh.", "cowCareJobCooldown": "Minimal 24 jam game absolut harus berlalu di antara tugas yang selesai.", "cowUseSuppliesFirst": "Stok yang dimiliki cukup untuk jam berikutnya. Tempatkan atau gunakan dahulu.", "cowUseMilkFirst": "Kirim susu layak dahulu. Bersihkan/buang gratis dapat membuka reservoir siap perah sebelum meminta bantuan.", "cowUseMarketFirst": "Persediaan minimum yang kurang masih terjangkau. Gunakan jalur Pasar biasa.", "cowCareJobWait": "Kerjakan 8 jam game biasa sebelum selesai. Syarat diperiksa lagi.", "cowCareJobStarted": "Tugas perawatan dimulai. Lanjutkan waktu game bersama; tanpa menunggu jam dunia nyata.", "cowCareJobCompleted": "Jatah khusus tugas perawatan diperoleh sekali. Tempatkan di palung Sapi; sisa hak jatah tetap tersimpan.", "cow_recovery_grant": "Jatah khusus tugas perawatan Koperasi"});

