Object.assign(COW_MESSAGES.en,{"cowThirdCow": "One third dairy cow", "cowBuyAdult": "Buy adult lactating cow", "cowPurchaseHelp": "V 1 allows three cows. First expand the barn and provide capacity plus owned supplies for 24 hot game hours:24 kg feed and 135 L water. Buying consumes only 240 Coins; it adds no milk or ration.", "cowPurchaseReady": "Capacity and owned supplies meet the three-cow requirement.", "cowNoMoreCows": "V 1 stops at three cows. No resale, replacement or fourth-cow loop.", "cowExpandFirst": "Build Bigger Dairy first: herd capacity 2→3.", "cowNeedCompanions": "Two existing cows must remain before this purchase.", "cowFeedCapacity": "Feed capacity must support 24 kg.", "cowWaterCapacity": "Upgrade the drinking trough: at least 135 L capacity is required.", "cowNeedFeedDay": "Have at least 24 kg usable owned Cow feed before buying.", "cowNeedWaterDay": "Have at least 135 L usable Cow/shared water before buying.", "cowFeedCapacityLabel": "Feed capacity", "cowWaterCapacityLabel": "Drinking capacity", "cowPurchased": "Your third adult, already-lactating cow arrived with an empty reservoir. Owned supplies were not consumed or replenished.", "cow_purchase": "Third dairy cow purchase", "cowBarnExpansion": "Bigger Dairy: space for three", "cowBarnExpansionHelp": "Raises herd capacity from 2 to 3 for 180 Coins. Then buy one adult cow for 240 Coins once feed/water capacity and a full hot day of owned supplies are ready.", "cowBarnExpanded": "Barn expanded to three spaces. No extra cow or supplies were granted.", "cow_barn_upgrade": "Bigger Dairy expansion", "cowDairyGoals": "Dairy goals", "cowGoalComplete": "Complete", "cowHappyGoal": "Happy Cows", "cowHappyHelp": "Accumulate 72 well-cared game hours with adequate feed/water, comfort, condition and clean resting space. Progress pauses during shortages and never resets offline.", "cowCoolGoal": "Cool the Milk", "cowCoolHelp": "Pay for 24 active cooling hours while milk is still valid. Rejected milk never earns this progress.", "cowHeatGoal": "Heat Wave", "cowHeatHelp": "Accumulate 24 healthy hot-weather hours with shade. Hot weather comes from the shared forecast.", "cowBiggerGoal": "Bigger Dairy", "cowBiggerHelp": "Expand 2→3, meet capacities and one hot day of owned feed/water, then buy the third already-lactating cow. Capacity alone is not completion."});

